export type DeploymentFeedbackType = {
    thumbs?: boolean;
    edits?: boolean;
    issues?: boolean;
    agentFeedback?: boolean;
    /**
     * URL to also POST detailed feedback submissions to (e.g. a self-hosted
     * customer's capture endpoint). Relative values resolve against the docs origin.
     */
    forwardEndpoint?: string;
    contextualFeedback?: {
        textInputOnly?: boolean;
        allowEmail?: boolean;
        emailDisclaimer?: string;
    };
};
